Class Punto
  Define x As Integer;
  Define yy As Integer;
EndClass

Algorithm Puntos
  Define p As Punto <- New Punto();
  p.x <- 3;
  p.yy <- 4;
  Write p.x, ",", p.yy;
EndAlgorithm

Class Caja
  Private Define secreto As Integer;
EndClass

Algorithm Espiar
  Define c As Caja <- New Caja();
  c.secreto <- 1;
EndAlgorithm
